import sys
from xml.dom import minidom

doc = minidom.parse('unpacked/word/document.xml')
body = doc.getElementsByTagName('w:body')[0]

ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}

def local(el):
    return el.tagName.split(':')[-1] if ':' in el.tagName else el.tagName

def text_of(p):
    parts = []
    for t in p.getElementsByTagName('w:t'):
        parts.append(t.firstChild.nodeValue if t.firstChild else '')
    return ''.join(parts)

for i, p in enumerate(body.getElementsByTagName('w:p')):
    pPr = p.getElementsByTagName('w:pPr')
    style = ''
    if pPr:
        ps = pPr[0].getElementsByTagName('w:pStyle')
        if ps:
            style = ps[0].getAttribute('w:val')
    txt = text_of(p).strip()
    if txt or style:
        print(f"{i:4d} | style={style or '-':12s} | {txt[:80]}")

